{"content": "#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelLayerNorm {
public:
    __aicore__ inline KernelLayerNorm() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                int64_t N, float eps) {
        xGm.SetGlobalBuffer((__gm__ T*)x, totalLength);
        gammaGm.SetGlobalBuffer((__gm__ T*)gamma, N);
        betaGm.SetGlobalBuffer((__gm__ T*)beta, N);
        yGm.SetGlobalBuffer((__gm__ T*)y, totalLength);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueGamma, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueBeta, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        pipe.InitBuffer(castQueueX, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(castQueueGamma, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(castQueueBeta, BUFFER_NUM, tileLength * sizeof(float));
        pipe.InitBuffer(castQueueY, BUFFER_NUM, tileLength * sizeof(float));

        pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
        pipe.InitBuffer(reduceWorkBuf, tileLength * sizeof(float));
        pipe.InitBuffer(meanBuf, 64);
        pipe.InitBuffer(varBuf, 64);

        this->formerNum = formerNum;
        this->formerLength = formerLength;
        this->tailNum = tailNum;
        this->tailLength = tailLength;
        this->tileLength = tileLength;
        this->N = N;
        this->eps = eps;
        this->totalLength = totalLength;
    }

    __aicore__ inline void Process() {
        int64_t loopCount = formerNum + tailNum;
        for (int64_t i = 0; i < loopCount; i++) {
            int64_t curTileLength = (i < formerNum) ? formerLength : tailLength;
            int64_t rowIdx = GetBlockIdx() * loopCount + i;
            if (rowIdx * N >= totalLength) {
                break;
            }

            CopyIn(rowIdx, curTileLength);
            Compute(rowIdx, curTileLength);
            CopyOut(rowIdx, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t rowIdx, int64_t curTileLength) {
        LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        LocalTensor<T> gammaLocal = inQueueGamma.AllocTensor<T>();
        LocalTensor<T> betaLocal = inQueueBeta.AllocTensor<T>();

        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        DataCopyPad(xLocal, xGm[rowIdx * N], DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0}, padParams);
        DataCopyPad(gammaLocal, gammaGm[0], DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0}, padParams);
        DataCopyPad(betaLocal, betaGm[0], DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0}, padParams);

        inQueueX.EnQue(xLocal);
        inQueueGamma.EnQue(gammaLocal);
        inQueueBeta.EnQue(betaLocal);
    }

    __aicore__ inline void Compute(int64_t rowIdx, int64_t curTileLength) {
        LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        LocalTensor<T> gammaLocal = inQueueGamma.DeQue<T>();
        LocalTensor<T> betaLocal = inQueueBeta.DeQue<T>();

        LocalTensor<float> xFp32 = castQueueX.AllocTensor<float>();
        LocalTensor<float> gammaFp32 = castQueueGamma.AllocTensor<float>();
        LocalTensor<float> betaFp32 = castQueueBeta.AllocTensor<float>();
        LocalTensor<float> yFp32 = castQueueY.AllocTensor<float>();

        AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        AscendC::Cast(gammaFp32, gammaLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
        AscendC::Cast(betaFp32, betaLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

        LocalTensor<float> tmpLocal = tmpBuf.Get<float>();
        LocalTensor<float> tmpLocal2 = tmpBuf2.Get<float>();
        LocalTensor<float> reduceWork = reduceWorkBuf.Get<float>();
        LocalTensor<float> meanLocal = meanBuf.Get<float>();
        LocalTensor<float> varLocal = varBuf.Get<float>();

        // Step 1: Compute mean = sum(x) / N
        AscendC::Duplicate(reduceWork, 0.0f, curTileLength);
        AscendC::Add(reduceWork, xFp32, reduceWork, curTileLength);
        float meanVal = 0.0f;
        for (int64_t j = 0; j < curTileLength; j++) {
            meanVal += xFp32.GetValue(j);
        }
        meanVal = meanVal / static_cast<float>(N);
        meanLocal.SetValue(0, meanVal);

        // Step 2: Compute (x - mean)
        AscendC::Duplicate(tmpLocal, meanVal, curTileLength);
        AscendC::Sub(tmpLocal, xFp32, tmpLocal, curTileLength);

        // Step 3: Compute variance = sum((x - mean)^2) / N
        AscendC::Mul(tmpLocal2, tmpLocal, tmpLocal, curTileLength);
        float varVal = 0.0f;
        for (int64_t j = 0; j < curTileLength; j++) {
            varVal += tmpLocal2.GetValue(j);
        }
        varVal = varVal / static_cast<float>(N);
        varLocal.SetValue(0, varVal);

        // Step 4: Compute rsqrt(var + eps)
        float rsqrtVal = 1.0f / sqrtf(varVal + eps);
        varLocal.SetValue(0, rsqrtVal);

        // Step 5: Normalize: (x - mean) * rsqrt(var + eps)
        AscendC::Duplicate(tmpLocal2, rsqrtVal, curTileLength);
        AscendC::Mul(tmpLocal, tmpLocal, tmpLocal2, curTileLength);

        // Step 6: Apply gamma and beta
        AscendC::Mul(tmpLocal, tmpLocal, gammaFp32, curTileLength);
        AscendC::Add(tmpLocal, tmpLocal, betaFp32, curTileLength);

        // Step 7: Cast back to output dtype
        AscendC::Cast(yFp32, tmpLocal, AscendC::RoundMode::CAST_ROUND, curTileLength);

        outQueueY.EnQue(yFp32);

        inQueueX.FreeTensor(xLocal);
        inQueueGamma.FreeTensor(gammaLocal);
        inQueueBeta.FreeTensor(betaLocal);
        castQueueX.FreeTensor(xFp32);
        castQueueGamma.FreeTensor(gammaFp32);
        castQueueBeta.FreeTensor(betaFp32);
    }

    __aicore__ inline void CopyOut(int64_t rowIdx, int64_t curTileLength) {
        LocalTensor<float> yFp32 = outQueueY.DeQue<float>();
        LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        DataCopyPad(yGm[rowIdx * N], yLocal, DataCopyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0});

        outQueueY.FreeTensor(yFp32);
        outQueueY.FreeTensor(yLocal);
    }

private:
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueX;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueGamma;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueBeta;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueueY;

    TQue<QuePosition::VECIN, BUFFER_NUM> castQueueX;
    TQue<QuePosition::VECIN, BUFFER_NUM> castQueueGamma;
    TQue<QuePosition::VECIN, BUFFER_NUM> castQueueBeta;
    TQue<QuePosition::VECOUT, BUFFER_NUM> castQueueY;

    TBuf<QuePosition::VECCALC> tmpBuf;
    TBuf<QuePosition::VECCALC> tmpBuf2;
    TBuf<QuePosition::VECCALC> reduceWorkBuf;
    TBuf<QuePosition::VECCALC> meanBuf;
    TBuf<QuePosition::VECCALC> varBuf;

    GlobalTensor<T> xGm;
    GlobalTensor<T> gammaGm;
    GlobalTensor<T> betaGm;
    GlobalTensor<T> yGm;

    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t N;
    float eps;
    int64_t totalLength;
};

extern "C" __global__ __aicore__ void layer_norm(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                                   int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                                   int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                                   int64_t N, float eps) {
    KernelLayerNorm<half> op;
    op.Init(x, gamma, beta, y, totalLength, formerNum, formerLength, tailNum, tailLength, tileLength, N, eps);
    op.Process();
}

extern "C" __global__ __aicore__ void layer_norm_float(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                                        int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                                        int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                                        int64_t N, float eps) {
    KernelLayerNorm<float> op;
    op.Init(x, gamma, beta, y, totalLength, formerNum, formerLength, tailNum, tailLength, tileLength, N, eps);
    op.Process();
}

extern "C" __global__ __aicore__ void layer_norm_bfloat16(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                                           int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                                           int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                                           int64_t N, float eps) {
    KernelLayerNorm<bfloat16_t> op;
    op.Init(x, gamma, beta, y, totalLength, formerNum, formerLength, tailNum, tailLength, tileLength, N, eps);
    op.Process();
}
