{"content": "#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_layer_norm.h"
#include "aclrtlaunch_layer_norm_float.h"
#include "aclrtlaunch_layer_norm_bfloat16.h"

namespace ascend_kernel {

at::Tensor layer_norm(const at::Tensor& x, at::IntArrayRef normalized_shape,
                      const c10::optional<at::Tensor>& weight,
                      const c10::optional<at::Tensor>& bias,
                      double eps) {
    // Compute M and N
    int64_t N = 1;
    for (auto dim : normalized_shape) {
        N *= dim;
    }
    int64_t M = x.numel() / N;

    // Create output tensor
    auto y = at::empty_like(x);

    // Handle optional weight and bias
    auto dtype = x.scalar_type();
    auto device = x.device();
    at::Tensor gamma;
    at::Tensor beta;
    if (weight.has_value() && weight->defined()) {
        gamma = weight.value().reshape({N});
    } else {
        gamma = at::ones({N}, at::TensorOptions().dtype(dtype).device(device));
    }
    if (bias.has_value() && bias->defined()) {
        beta = bias.value().reshape({N});
    } else {
        beta = at::zeros({N}, at::TensorOptions().dtype(dtype).device(device));
    }

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int64_t totalLength = x.numel();
    int64_t blockDim = coreNum;

    // Each core handles some rows
    int64_t rowsPerCore = (M + blockDim - 1) / blockDim;
    int64_t totalLengthCore = rowsPerCore * N;

    // Cache Line 512B alignment
    int64_t totalLengthCoreAlign = ((totalLengthCore * x.element_size() + 511) / 512) * 512 / x.element_size();
    if (totalLengthCoreAlign > totalLengthCore) {
        totalLengthCoreAlign = totalLengthCore;
    }

    int64_t formerNum = totalLengthCore / totalLengthCoreAlign;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailNum = (totalLengthCore % totalLengthCoreAlign > 0) ? 1 : 0;
    int64_t tailLength = totalLengthCore % totalLengthCoreAlign;

    // UB-level tiling
    int64_t dtypeSize = x.element_size();
    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
    int64_t tileLength = (ubSize / bufferCoefficient) / dtypeSize;
    tileLength = (tileLength / 32) * 32;  // 32B align
    if (tileLength > N) {
        tileLength = N;
    }
    if (tileLength < 32) {
        tileLength = 32;
    }

    float eps_f = static_cast<float>(eps);

    // Launch kernel based on dtype
    if (x.scalar_type() == at::ScalarType::Half) {
        EXEC_KERNEL_CMD(layer_norm, blockDim, x, gamma, beta, y,
                        totalLength, formerNum, formerLength, tailNum, tailLength,
                        tileLength, N, eps_f);
    } else if (x.scalar_type() == at::ScalarType::Float) {
        EXEC_KERNEL_CMD(layer_norm_float, blockDim, x, gamma, beta, y,
                        totalLength, formerNum, formerLength, tailNum, tailLength,
                        tileLength, N, eps_f);
    } else if (x.scalar_type() == at::ScalarType::BFloat16) {
        EXEC_KERNEL_CMD(layer_norm_bfloat16, blockDim, x, gamma, beta, y,
                        totalLength, formerNum, formerLength, tailNum, tailLength,
                        tileLength, N, eps_f);
    } else {
        TORCH_CHECK(false, "Unsupported dtype for layer_norm");
    }

    return y;
}

} // namespace ascend_kernel
