7	at::Tensor layer_norm(const at::Tensor& x, at::IntArrayRef normalized_shape,
8	                      const c10::optional<at::Tensor>& weight,
9	                      const c10::optional<at::Tensor>& bias,
10	                      double eps) {
11	    // Compute M and N
12	    int64_t N = 1;
13	    for (auto dim : normalized_shape) {
14	        N *= dim;
15	    }
16	    int64_t M = x.numel() / N;
17	
18	    // Create output tensor
19	    auto y = at::empty_like(x);
20	
21	    // Handle optional weight and bias
22	    auto dtype = x.scalar_type();
23	    auto device = x.device();
24	    at::Tensor gamma;
25	    at::Tensor beta;
26	    if (weight.has_value() && weight->defined()) {
27	        gamma = weight.value().reshape({N});
28	    } else {
29	        gamma = at::ones({N}, at::TensorOptions().dtype(dtype).device(device));
30	    }
31	    if (bias.has_value() && bias->defined()) {
32	        beta = bias.value().reshape({N});
33	    } else {
34	        beta = at::zeros({N}, at::TensorOptions().dtype(dtype).device(device));
35	    }
36	
37	    // Get platform info
38	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
39	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
40	    uint64_t ubSize;
41	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
42	
43	    // Block-level tiling
44	    int64_t blockDim = coreNum;
45	    int64_t blockM = 8;  // rows per block
46	
47	    // Each core handles some blocks
48	    int64_t totalBlocks = (M + blockM - 1) / blockM;
49	    int64_t usedCoreNum = std::min(coreNum, totalBlocks);
50	    int64_t tasksPerCore = (totalBlocks + usedCoreNum - 1) / usedCoreNum;
51	
52	    float eps_f = static_cast<float>(eps);
53	
54	    // Dtype flag: 0=fp32, 1=fp16, 2=bf16
55	    int64_t dtypeFlag = 1;
56	    if (x.scalar_type() == at::ScalarType::Float) {
57	        dtypeFlag = 0;
58	    } else if (x.scalar_type() == at::ScalarType::BFloat16) {
59	        dtypeFlag = 2;
60	    }
61	
62	    // Launch kernel
63	    EXEC_KERNEL_CMD(layer_norm, blockDim, x, gamma, beta, y,
64	                    M, N, blockM, usedCoreNum, tasksPerCore, eps_f, dtypeFlag);
65	
66	    return y;
67	}
