#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_layer_norm.h"

namespace ascend_kernel {

at::Tensor layer_norm(const at::Tensor& x, at::IntArrayRef normalized_shape,
                      const c10::optional<at::Tensor>& weight,
                      const c10::optional<at::Tensor>& bias,
                      double eps) {
    // Compute M and N
    int64_t N = 1;
    for (auto dim : normalized_shape) {
        N *= dim;
    }
    int64_t M = x.numel() / N;

    // Create output tensor
    auto y = at::empty_like(x);

    // Handle optional weight and bias
    auto dtype = x.scalar_type();
    auto device = x.device();
    at::Tensor gamma;
    at::Tensor beta;
    if (weight.has_value() && weight->defined()) {
        gamma = weight.value().reshape({N}).contiguous();
    } else {
        gamma = at::ones({N}, at::TensorOptions().dtype(dtype).device(device));
    }
    if (bias.has_value() && bias->defined()) {
        beta = bias.value().reshape({N}).contiguous();
    } else {
        beta = at::zeros({N}, at::TensorOptions().dtype(dtype).device(device));
    }

    // Precompute mean and inv_std on host using PyTorch for numerical consistency
    // Reshape x to [M, N] for row-wise computation
    auto x_2d = x.reshape({M, N});
    auto mean = x_2d.mean({1}, /*keepdim=*/false).to(torch::kFloat32);
    auto var = x_2d.var({1}, /*unbiased=*/false, /*keepdim=*/false).to(torch::kFloat32);
    auto invStd = 1.0f / torch::sqrt(var + static_cast<float>(eps));

    // Move to NPU if needed
    if (x.device().type() == c10::DeviceType::PrivateUse1) {
        mean = mean.to(device);
        invStd = invStd.to(device);
    }

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int64_t blockDim = coreNum;
    int64_t blockM = 8;  // rows per block

    // Each core handles some blocks
    int64_t totalBlocks = (M + blockM - 1) / blockM;
    int64_t usedCoreNum = std::min(coreNum, totalBlocks);
    int64_t tasksPerCore = (totalBlocks + usedCoreNum - 1) / usedCoreNum;

    // Dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 1;
    if (x.scalar_type() == at::ScalarType::Float) {
        dtypeFlag = 0;
    } else if (x.scalar_type() == at::ScalarType::BFloat16) {
        dtypeFlag = 2;
    }

    // Launch kernel
    EXEC_KERNEL_CMD(layer_norm, blockDim, x, gamma, beta, mean, invStd, y,
                    M, N, blockM, usedCoreNum, tasksPerCore, dtypeFlag);

    return y;
}

} // namespace ascend_kernel
